EXTRAS = {
    "d1": dict(
        pressure=[
            dict(key="core", q="fan-out 编排层最核心的问题是什么？一句话说出它在解决什么矛盾。", a="核心矛盾是想用并发缩短主任务耗时，但每个子任务又有依赖、上下文隔离和副作用安全。假设一轮有 20 到 200 个子任务，单任务 2 到 60 秒，盲目全并发会把模型、工具或沙箱打爆；过度串行又浪费关键路径外的等待时间。所以编排层要把 Plan、SubTask、ExecutionLog 和 completed 结果表分开：DAG 决定能不能并行，context_keys 决定能看什么，idempotency_key 决定副作用能不能恢复。代价是多一次持久化和调度延迟，兜底是小规模先用单进程执行器，超过阈值再启用队列 worker。指标看端到端耗时、关键路径耗时和副作用重复执行数。"),
            dict(key="scale", q="这个编排层按多大规模设计？规模变化会改变哪个关键决定？", a="我会先给假设：在线请求每秒 50 到 200 轮，每轮 10 到 100 个节点，节点产物 1KB 到 1MB，P99 节点耗时 30 秒。这个规模下，调度状态放数据库或持久队列，热路径用内存 ready 集合缓存即可。如果变成每轮上千节点或全站每秒几万节点，关键决定会从进程内线程池变成分布式任务队列，并且 indegree、children 和 node_status 要做分片，避免一个大 Plan 锁住单行。规模再大时还要限制 fan-out 宽度，比如每轮最多 64 个 running 节点，超出进入 ready_waiting。兜底是按租户降级并拒绝新图，指标看 ready 等待 P99、调度循环耗时和单 Plan 状态大小。"),
            dict(key="authority", q="任务是否完成、能不能解锁下游，权威状态在哪里？缓存和日志分别干什么？", a="权威状态必须在持久化 ExecutionLog 和 TaskState 表，不在 worker 内存。TaskState 里至少有 plan_id、task_id、attempt、status、lease_token、result_ref、error_class、updated_at；ExecutionLog 记录状态迁移，便于恢复和审计。内存 ready 队列只是加速视图，丢了可以从入度、completed 和 failed 重建。缓存可以保存上下文切片或小产物，但不能决定成功。日志用于追加事实，数据库当前表用于快速查询谁能跑。这样做的代价是每个节点多一次写放大；兜底是批量刷新非关键日志，但 completed 和副作用结果必须同步写。指标看恢复重建耗时、缓存命中率和日志与当前表不一致次数。"),
            dict(key="crash", q="最坏时刻挂了怎么办：刚发出副作用、还没写 completed，或者持锁时进程死了？", a="最坏点是副作用已经发给外部系统，本地还停在 running。机制上执行前先写 intent，字段包括 idempotency_key、request_hash、attempt 和 lease_token；外部调用必须带这个幂等键。恢复时扫描 running 且 lease 过期的任务，如果是无副作用任务可以重试；如果有副作用，先用 idempotency_key 查询外部结果，查到成功再写 completed，查不到再按工具语义重试或转人工确认。持锁死亡靠 lease_at 和 ttl 回收，提交结果时必须带 fencing token，旧 worker 即使醒来也写不进去。代价是工具要支持查询或幂等；兜底是把未知状态标为 blocked，不继续解锁下游。指标看 unknown_inflight 数、副作用重复数和恢复 RTO，假设目标 RTO 5 分钟内。"),
            dict(key="dup", q="同一个子任务重复、乱序、丢失分别怎么处理？", a="重复来自客户端重试、worker 超时和租约接管，所以 task_id 加 attempt 不能当幂等键，幂等键要来自 plan_id、task_id 和业务输入哈希。重复领取时通过 status in completed 直接返回 result_ref，通过 lease_token 拒绝旧尝试。乱序主要是下游先于上游完成或旧 attempt 晚到，机制是 indegree 只由权威 completed 递减，结果提交时检查 expected_attempt 和 fencing token。丢失是 ready 消息投递失败或进程重启，兜底是定期 reconcile：从 TaskState 重算 ready 条件，把 pending 且所有依赖完成的节点补回队列。代价是 reconcile 有扫描成本，可按 plan_id 分片。指标看重复领取率、旧 attempt 拒写次数和 ready 丢失修复数。"),
            dict(key="multi", q="多实例部署时，怎么避免同一个子任务被两个 worker 同时执行并提交？", a="多实例下不能依赖本地 running 集合。领取任务时对 TaskState 做 CAS：status 从 ready 改 running，同时写 owner_id、lease_token、lease_expire_at 和 attempt。worker 心跳只延长自己 token 的租约；提交时 where 条件带 plan_id、task_id、attempt、lease_token 和状态 running，成功后写 result_ref 并把状态改 completed。lease 过期后新 worker 可以接管并生成更大的 fencing token，外部副作用调用也带 token 或幂等键，旧 worker 的迟到提交会被数据库拒绝。代价是数据库写热点上升，兜底是按 plan_id 或租户分片队列。指标看同任务并发执行探测数、CAS 失败率和 lease 接管成功率。"),
            dict(key="region", q="多机房怎么做？RTO/RPO 多少？为什么不直接 active-active？", a="这个系统的权威状态有强顺序依赖，默认我选单主多读的区域部署：一个主区域负责 TaskState、ExecutionLog 和幂等结果，备区域异步复制。假设面向在线编排，RTO 15 分钟，RPO 小于 30 秒；如果副作用任务占比高，RPO 要接近 0，就需要同步复制或暂停接管前对账。不是 active-active 的原因是同一 plan 的 indegree、lease 和 completed 需要线性化，双主会让同一任务在两个区域同时解锁下游。兜底是区域故障后冻结新提交，备区先重放日志、扫描 running、对账副作用，再恢复调度。指标看复制延迟、跨区接管耗时和接管后的重复副作用数。"),
            dict(key="tenx", q="流量涨 10 倍时，最先坏在哪里？怎么提前发现并扩容？", a="10 倍流量下最先坏的通常不是执行线程，而是调度状态写入、ready 队列长度和下游模型或工具配额。假设从每秒 1 千节点涨到 1 万节点，TaskState 更新和 ExecutionLog 追加会变成写热点，ready_wait_ms P99 会先升高；如果还无限重试，会进一步放大下游 429。提前发现要看三个水位：数据库写延迟、每租户 ready 队列长度、外部资源限流命中率。扩容顺序是先按租户和 plan 分片队列，再水平扩 worker，最后拆日志冷表；同时收紧每轮 max_parallel，避免扩容前把下游打穿。兜底是新计划准入降级，只允许关键任务进队。指标看排队 P99、重试放大倍数和限流误杀率。"),
            dict(key="choice", q="为什么要用 DAG 加持久化状态机？不用它，只用异步任务列表行不行？", a="约束是子任务有依赖、部分失败和恢复要求，单纯异步列表只能表示开始和结束，难以证明哪个下游能跑。我选 DAG 加持久化状态机：DAG 的 indegree/children 管依赖，TaskState 的 pending、ready、running、completed、failed、skipped 管生命周期。备选是固定阶段流水线或纯消息队列。固定阶段适合流程稳定，但无法表达动态 fan-out；纯消息队列吞吐高，但消息本身不是权威状态，崩溃后难以重算 ready。缺点是实现复杂、写放大明显；兜底是小任务合批、日志异步归档。用关键路径耗时下降、恢复成功率和重复副作用数证明选择有效。"),
            dict(key="rollout", q="这个编排层怎么灰度、回滚，并证明比串行或旧编排更好？", a="灰度要按租户和任务类型开关，先只接无副作用、节点数小于 20 的 plan，再放开副作用节点和大 fan-out。每轮执行记录 strategy_version、max_parallel、context_bytes、node_status 分布和最终结果，方便和旧编排做对照。回滚不是删状态，而是停止新 plan 使用新策略，已运行 plan 继续按原 strategy_version 跑完，避免同一轮中途换调度语义。止损线可以设为副作用重复数大于 0、失败率升高 1 个百分点、ready P99 超过 30 秒。收益看关键路径耗时下降、成功率不降、成本和下游 429 不升。口径要排除外部系统整段不可用的时间，否则会把编排收益淹没。"),
        ],
        metrics=[
            dict(name="关键路径缩短率", ask="你说并发编排能提速，分子分母到底是什么？", numerator="同类任务在串行基线耗时减去新编排端到端耗时的差值，按完成轮次聚合", denominator="同类任务在串行基线下的端到端耗时，按 plan_id 和任务类型匹配", exclude="排除外部模型或工具整段不可用、人工取消、输入规模差异超过 20% 的轮次，因为这些不反映编排能力", traps=["只看平均值会掩盖 P99 退化", "把部分成功当全成功会虚高收益", "不同 DAG 宽度混在一起比较不公平"], answer="采集时每个 plan 记录节点数、边数、max_parallel、critical_path_ms 和 end_to_end_ms。线上灰度可以用同类型任务的历史串行基线，也可以对低风险任务做影子计划估算串行耗时。展示时我会同时看 P50、P95、P99 和按 DAG 宽度分桶的比率，而不是只报一个平均提速。部分失败的 plan 单独统计，因为它可能很快结束但业务没完成，不能算提速成功。"),
            dict(name="副作用重复执行率", ask="你说不会重复执行副作用，怎么定义重复？", numerator="同一 plan_id、task_id、idempotency_key 对外产生两次及以上成功副作用的任务数", denominator="所有声明 has_side_effect 且进入执行阶段的任务数", exclude="排除外部系统返回同一幂等结果的重放查询，因为它没有产生第二次业务副作用", traps=["把重复请求等同于重复副作用会误报", "只看本地 completed 会漏掉本地崩溃后的外部成功", "按 attempt 做分母会稀释问题"], answer="这个指标需要本地 ToolCall 表和外部幂等查询一起采集。本地记录 intent、attempt、idempotency_key 和 external_result_id；恢复时如果同一幂等键拿到同一个 result_id，算幂等命中，不算重复。只有出现两个不同成功 result_id，或外部审计确认执行了两次，才进分子。粒度按任务而不是 attempt，因为重试越多越不能稀释风险。这个指标目标应接近零，一旦非零就触发止损。"),
            dict(name="恢复可复用率", ask="崩溃恢复后你说能复用 checkpoint，分母是什么？", numerator="恢复扫描中直接复用 completed result 或通过幂等键对账成功的节点数", denominator="恢复扫描时处于 running、unknown 或 ready 丢失状态的节点数", exclude="排除确定性参数错误和用户主动取消的节点，因为它们不应该通过恢复继续跑", traps=["把重新执行成功算复用会虚高", "只按 plan 统计会掩盖节点级丢失", "没有区分副作用和无副作用节点"], answer="采集时每次进程重启或 lease 接管生成 recovery_id，把扫描到的异常节点逐个记录 recovery_action：reuse_completed、reconcile_external、retry、blocked。恢复可复用率只统计前两类，按节点粒度看整体和副作用节点两个口径。还要看恢复耗时 P99，因为复用率高但扫描半小时也不可接受。常见陷阱是把重跑后成功也算恢复无损，这只能说明最终成功，不能证明没有重复成本或副作用风险。"),
        ],
        choices=[
            dict(topic="调度状态存哪里", constraint="子任务会跨进程恢复，ready 队列可以丢，但完成结果和副作用意图不能丢。", choice="选择关系型数据库保存 TaskState 和 ExecutionLog，队列只承载可重建的 ready 消息。", alternatives="备选是纯内存线程池、只用消息队列保存状态，或者把全部状态塞进缓存。", why_not="纯内存无法恢复，纯队列难以表达依赖和 completed 查询，缓存过期会破坏权威语义。", downside="缺点是每个节点有写放大和行锁竞争；兜底是按 plan 分片、批量归档日志、只把必要字段放热表。", metric="用恢复成功率、TaskState 写入 P99、ready 重建耗时和重复副作用数证明。"),
            dict(topic="并发上限怎么定", constraint="并发要缩短关键路径，但不能让租户、模型、工具或沙箱被瞬时 fan-out 打爆。", choice="选择全局 semaphore 加租户和资源维度令牌桶，节点领取前同时通过这些准入。", alternatives="备选是固定线程池、每个 plan 自己限流，或者只依赖下游返回 429 再重试。", why_not="固定线程池不能隔离热点租户，plan 内限流看不到全局资源，等 429 再退避会放大流量。", downside="缺点是策略参数复杂，可能误杀低风险任务；兜底是保守默认值、按资源标签动态调参和人工白名单。", metric="用限流命中率、限流误杀率、下游 429 率、ready 等待 P99 和关键路径耗时证明。"),
        ],
    ),
    "d2": dict(
        pressure=[
            dict(key="core", q="Agent 会话无损续跑最核心的问题是什么？", a="核心矛盾是 Agent loop 会持续产生消息、工具调用和流式事件，但用户断线和进程崩溃会把一次逻辑 step 切在任意位置。无损不是说网络包恰好一次，而是恢复后会话协议完整、已承诺事件可补发、有副作用工具不重复。假设单会话 10 到 200 个 step，事件每秒 5 到 50 条，工具 1 到 20 次；机制上用 SessionLog 记录 messages/current_step，用 ToolCall 表记录 intent、status、idempotency_key，用 EventLog 记录 seq 和 payload。代价是写日志多、延迟略升；兜底是未落盘内容不对外承诺，未知副作用转对账或人工。指标看续跑成功率、事件缺口率和副作用重复执行率。"),
            dict(key="scale", q="会话续跑按什么 QPS、状态大小和保留时间设计？", a="我会先假设在线 10 万活跃会话，入口 1 千 QPS，单会话串行，messages 热状态 100KB 到 5MB，EventLog 保留 24 小时或直到客户端 ack 后再延迟清理。规模小的时候 SessionState 可以整块写；当 messages 超过几 MB 或事件超过几万条，关键决定就变成追加日志加周期 checkpoint，而不是每个 token 全量覆盖。模型流式 token 可以合并成 100 到 500 毫秒一个事件，降低写放大。兜底是老消息摘要化但保留未完成 tool_call 和 tool result。指标看 checkpoint 写入 P99、EventLog 积压字节、恢复加载耗时和裁剪后协议错误数。"),
            dict(key="authority", q="恢复时到底谁说了算？内存、客户端 ack、日志和数据库各自角色是什么？", a="权威状态在持久化 SessionLog、ToolCall 表和 EventLog，不在客户端也不在进程内存。SessionLog 决定 messages、current_step、last_committed_step；ToolCall 表决定某个 call_id 是 pending、inflight、completed 还是 unknown；EventLog 决定哪些 seq 已经对外承诺。客户端 ack 只推进可清理水位，不能证明服务端没有事件。内存缓存只是加速当前 step，崩溃后丢弃即可。这样做的代价是每个事件先落盘再发送，首 token 延迟会上升；兜底是批量落盘展示 token，但 step 边界和工具事件必须同步。指标看 ack 滞后、日志重放耗时和内存缓存回源率。"),
            dict(key="crash", q="如果模型流式输出一半崩了，或工具调用发出后本地没写结果，怎么恢复？", a="模型流式中间崩溃要按承诺边界处理：已经写入 EventLog 的 token 按 seq 补发，已经写入 assistant_message_delta 的内容继续拼接；未落盘 token 视为没有发生，不能假装补齐。为了避免半条 assistant 消息破坏协议，可以有 message_part 状态和 finish_reason，恢复时若未完成就从最近 step checkpoint 重新调用或生成一个可解释的中断事件，取决于产品语义。工具调用更严格，执行前先写 ToolCall intent，发出后崩溃就用 idempotency_key 查询外部结果；查到成功回写 tool result，查不到才重试。兜底是 unknown 状态阻塞后续模型 step。指标看 unknown_toolcall 数和流式恢复缺口。"),
            dict(key="dup", q="客户端重复提交、事件乱序、日志丢失分别怎么处理？", a="重复提交用 request_id 和 session_id 去重，同一 request_id 已入队就返回原 input_seq，不再追加用户消息。事件乱序靠 EventLog 的单调 seq，发送层可以乱，客户端按 seq 缓冲和去重；服务端补发时从 last_event_id+1 开始。工具重复靠 call_id、参数哈希和 idempotency_key，参数变了但 call_id 相同要拒绝。日志丢失不能靠猜，写入必须先 fsync 或提交事务后再对外发送；如果发现 seq 缺口，恢复任务把会话标 degraded，停止继续 step 并提示重试或人工处理。代价是强持久化增加延迟；兜底是关键事件同步、展示 token 合批。指标看重复 request 命中率、事件缺口率和乱序缓冲长度。"),
            dict(key="multi", q="多实例下如何避免两个实例同时推进同一个会话 step？", a="同一 session 必须串行推进，所以多实例下要有 SessionLease。实例领取会话时原子写 owner_id、lease_token、lease_expire_at 和 session_version；每次追加 messages、ToolCall 或 EventLog 都带 session_version 做 CAS。lease 续约失败的旧实例必须停止发送；即使它还在跑模型，落盘也会因 fencing token 不匹配失败。多端输入只进入 SessionInputQueue，不直接触发并行 step。代价是一个会话被热点用户打满时只能串行；兜底是每处理一条消息后让出调度权，并给用户级并发做公平队列。指标看 lease 冲突数、旧 token 拒写数、会话锁等待 P99。"),
            dict(key="region", q="Agent 会话续跑多机房怎么设计？RTO/RPO 是多少？", a="会话状态强依赖顺序，默认按 session_id 固定主区域，EventLog 和 SessionLog 异步复制到备区。假设普通交互 RTO 10 到 30 分钟，RPO 30 秒内；如果有高价值副作用工具，工具 intent 和 completed 要同步复制或先写到跨区强一致存储，否则宁可恢复慢也不能重复执行。不是所有会话 active-active，因为同一 session 的 seq 和 messages 需要单调递增，双写会产生冲突。兜底是区域故障后在备区只恢复已复制到完整 checkpoint 的会话，unknown toolcall 先对账。指标看复制延迟、seq 缺口数、跨区恢复成功率和故障期间拒绝的新输入数。"),
            dict(key="tenx", q="活跃会话和事件量涨 10 倍，最先坏在哪里？怎么扩？", a="10 倍后最先坏的是 EventLog 写入和热会话锁，而不是模型本身。比如从 1 千 QPS 到 1 万 QPS，流式 token 如果逐条写库，会把存储 IOPS 打满；热点会话也会让 session lease 长时间占用。提前发现看 event_write_ms P99、每会话 pending_input 长度、ack_lag_seq 和 checkpoint_bytes。扩容方式是 token 事件合批、EventLog 按 session_id 分片、冷事件归档到对象存储、SessionState 只保留可恢复摘要；同时入口对单会话限速，避免一个用户产生无限 backlog。兜底是关闭低价值 token 级事件，只保留 step 级事件和最终输出。指标看补发成功率和首事件延迟是否守住目标。"),
            dict(key="choice", q="为什么要事件日志加 checkpoint？只保存最新 messages 行不行？", a="约束是恢复点可能落在模型流、工具调用和客户端发送之间，只保存最新 messages 无法知道哪些事件已承诺、哪些工具已发出。选择 EventLog 加 checkpoint：checkpoint 快速恢复 current_step，EventLog 保证客户端按 seq 续传，ToolCall intent 保证副作用对账。备选是每次全量覆盖 SessionState，或完全依赖客户端缓存。全量覆盖写放大且无法处理发送后崩溃；客户端缓存不能作为服务端权威。缺点是日志多、清理复杂；兜底是 ack 水位和 TTL 双条件清理。指标用恢复加载 P99、事件缺口率、存储字节每会话证明。"),
            dict(key="rollout", q="无损续跑怎么灰度、回滚、证明真的提升？", a="灰度先对只读工具和短会话开启，记录 runtime_version、event_schema_version、checkpoint_version 和是否使用新恢复逻辑。对照组仍用旧逻辑，但所有组都采集断线重连、进程重启注入和工具幂等结果。回滚时不能删除新 EventLog，而是停止新会话进入新版；已进入新版的会话按原 schema 跑完或用兼容读取器恢复。止损线是事件缺口率超过 0.1%、副作用重复非零、恢复 P99 超过 60 秒。收益不是只看 200 成功，而是看断线后用户可继续率、崩溃演练续跑成功率和重复工具调用下降。口径要排除用户主动清空会话和外部工具无查询能力的 blocked 样本。"),
        ],
        metrics=[
            dict(name="续跑成功率", ask="你说无损续跑 98%，分母是什么？", numerator="发生断线、进程重启或 lease 接管后，在目标 RTO 内恢复到一致 step 并继续完成或等待用户输入的会话数", denominator="所有触发恢复流程且恢复前已经有持久化 checkpoint 的会话数", exclude="排除用户主动删除会话、权限被撤销、外部副作用长期 unknown 的会话，因为它们不是运行时恢复能力", traps=["把重新开始一轮当续跑会虚高", "按请求统计会被重连风暴放大", "部分事件缺失但最终回答成功不能算无损"], answer="采集时每次恢复生成 recovery_id，记录原因、checkpoint_seq、last_event_id、恢复动作和最终状态。统计粒度按 session recovery，而不是 HTTP 请求或事件条数。成功必须同时满足 messages 协议完整、EventLog 无缺口、ToolCall 状态可解释，并在假设 RTO 60 秒内恢复。展示时除了比率，还要看恢复耗时 P50/P99 和失败分类，否则 98% 不知道是快恢复还是慢恢复。"),
            dict(name="事件缺口率", ask="事件流不丢不重怎么量化？重复补发算失败吗？", numerator="客户端或服务端检测到 seq 缺口且无法从 EventLog 补齐的会话事件流数量", denominator="所有发生过断线重连或补发的会话事件流数量", exclude="排除客户端 last_event_id 明显伪造或早于日志保留 TTL 的请求，因为已超出承诺保留窗口", traps=["把重复补发算缺口会误判", "只按事件条数会掩盖会话级失败", "没有记录日志保留窗口会把过期误当丢失"], answer="EventLog 为每个 session 维护连续 seq，客户端重连带 last_event_id，服务端补发时记录 from_seq、to_seq 和 missing_seq。重复补发不是失败，客户端按 seq 去重即可；真正失败是服务端承诺保留窗口内找不到某个 seq。这个指标按会话流统计，同时保留事件条数辅助定位。看比率之外，还要看 ack_lag 的 P99，因为 ack 长期落后会导致保留成本和过期风险上升。"),
            dict(name="工具幂等对账成功率", ask="工具调用中间崩了，你怎么证明没有重复副作用？", numerator="inflight 或 unknown ToolCall 通过 idempotency_key 查询到确定结果并成功回写 completed 的次数", denominator="恢复时发现状态为 inflight 或 unknown 且 has_side_effect 为真的 ToolCall 次数", exclude="排除纯读工具和未发出 intent 的工具，因为它们没有外部副作用对账需求", traps=["把直接重试成功算对账成功会虚高", "外部查询接口失败和业务未执行要分开", "按 attempt 统计会稀释多次未知"], answer="每个有副作用工具执行前写 intent，字段包括 call_id、request_hash、idempotency_key 和 external_ref。恢复时先查本地 completed，再查外部权威结果，只有查到确定成功或确定失败并写回 ToolCall，才算对账成功。无法查询要进入 blocked 或人工处理，不能自动算失败后重试。这个指标按 ToolCall 统计，并单独看 unknown 持续时长 P99，目标是未知尽快收敛且重复副作用为零。"),
        ],
        choices=[
            dict(topic="流式事件怎么存", constraint="客户端会断线，服务端会崩溃，已经展示给用户的 token 和状态事件必须可补发。", choice="选择按 session_id 追加 EventLog，事件带 seq、type、payload_hash、created_at 和 ack 清理水位。", alternatives="备选是只走长连接内存缓冲、让客户端自己缓存，或只保存最终回答。", why_not="内存缓冲崩溃即丢，客户端缓存不是服务端权威，只存最终回答无法恢复工具状态和中间承诺。", downside="缺点是 token 级日志写放大；兜底是小窗口合批、低价值 delta 合并、完成后按 ack 和 TTL 清理。", metric="用事件缺口率、补发 P99、每会话日志字节和首 token 延迟证明。"),
            dict(topic="副作用工具恢复", constraint="工具可能已经执行成功但本地崩溃，恢复时不能盲目重试产生第二次业务动作。", choice="选择意图先落盘、执行带幂等键、恢复先对账再回写 completed 的状态机。", alternatives="备选是失败后全部重试、只靠本地锁，或要求工具完全无副作用。", why_not="全部重试会重复副作用，本地锁崩溃后失效，要求无副作用不符合真实 Agent 能力。", downside="缺点是工具接入成本高，必须提供幂等键和查询语义；兜底是 unknown 状态阻塞并人工确认。", metric="用工具幂等对账成功率、unknown 工具数量、副作用重复执行率和恢复耗时证明。"),
        ],
    ),
    "d3": dict(
        pressure=[
            dict(key="core", q="Model Router 最核心的问题是什么？", a="核心矛盾是每次请求都想选质量高、便宜、低延迟的模型，但模型容量、限流、错误类型和业务优先级不断变化，不可能同时最优。Router 要把选择和保护上游放在同一层：请求字段有 tenant_id、task_type、priority、budget、deadline_ms、quality_floor；状态字段有模型健康、队列长度、令牌桶余量、熔断到期时间。假设入口 1 千 QPS，P99 目标 8 秒，多模型各自限额不同。机制是先筛候选，再按策略评分，准入失败时决定排队、快速失败或降级。代价是策略复杂且可能选错；兜底是固定安全模型和明确拒绝。指标看成功率、排队 P99、成本每请求和 fallback 后质量差。"),
            dict(key="scale", q="Router 的规模多大？QPS 或模型数变化会改变哪些设计？", a="假设 20 个模型、5 个供应商、100 个租户，入口 1 千到 5 千 QPS，单请求 1KB 到 200KB，上游延迟 1 到 60 秒。这个规模下，路由策略和模型目录可本地缓存，限流桶必须多实例共享。如果涨到 5 万 QPS，关键决定会变成把 tenant+model 的令牌桶放到 Redis，并用 Lua 原子扣减，避免每实例本地桶把总配额放大；同时队列要按 deadline 分片，不能一个全局优先队列。模型数涨多后，健康探测和策略评估要做增量缓存。兜底是超过队列等待预算就快速失败。指标看路由决策耗时、共享桶扣减 P99 和上游 429 率。"),
            dict(key="authority", q="模型健康、配额和路由结果谁说了算？本地缓存能不能做权威？", a="权威状态要分层：模型目录和策略版本来自配置中心或数据库；租户预算和配额余额来自计费或配额存储；短期限流令牌在共享限流器；本地缓存只保存只读策略和短 TTL 健康视图。请求的最终路由结果要落 RequestRouteLog，字段包括 request_id、policy_version、candidate_models、chosen_model、fallback_reason、quota_result。内存缓存不能说了算，因为多实例本地桶会把租户配额放大，健康缓存过期也会继续打故障模型。代价是共享限流器增加一次网络跳；兜底是 Redis 不可用时降级到本地保守配额，保护上游。指标看本地降级次数、配额超发率和策略版本不一致率。"),
            dict(key="crash", q="请求排队或已调用上游时 Router 实例挂了，会不会丢请求或重复扣费？", a="如果 Router 只是同步网关，进程挂掉时客户端会超时重试，所以 request_id 必须贯穿重试，RouteLog 记录 chosen_model 和 attempt。排队模式下，入队前先写 QueueItem，字段有 deadline_at、tenant_id、model_group、idempotency_key；出队扣令牌后再调用上游。实例在扣令牌后、调用前挂了，会造成令牌短暂损失，所以令牌桶要有短 TTL 预占或失败回补；调用上游后挂了，恢复无法取消，就依赖客户端重试和上游 request_id 去重。代价是恰好一次很难，只能做到请求级可解释。兜底是短 deadline 请求快速失败，不入持久队列。指标看预占令牌泄漏、客户端重试命中和未知 attempt 数。"),
            dict(key="dup", q="重复请求、乱序健康事件、限流结果丢失分别怎么处理？", a="重复请求用 client_request_id 或网关生成 request_id 去重，同一 request_id 如果已经有 chosen_model，就尽量沿用，避免第一次走便宜模型、第二次重试走昂贵模型。健康事件可能乱序，所以健康表带 observed_at 和 version，只接受更新的探测结果；熔断从 open 到 half_open 也要有到期时间。限流扣减结果如果丢失，宁可按失败处理或等待 TTL 回收，不能本地补发第二次扣减。429 和配额耗尽要分开：429 是模型瞬时限流，可退避或切副本；配额耗尽是租户预算不够，应切更便宜模型或拒绝。指标看去重命中率、过期健康事件丢弃数和配额超发率。"),
            dict(key="multi", q="多实例 Router 如何共享租户和模型配额，避免每个实例都放一份额度？", a="多实例的核心是共享桶。对 tenant_id+model_id 或 tenant_id+model_family 建 key，令牌数、last_refill_ms、daily_budget 和并发数都放共享存储，用 Lua 原子完成补充、扣减和返回 retry_after。实例本地只缓存静态策略，不缓存可消费配额；否则 10 个实例各放 100 QPS，会把上游打成 1000 QPS。对长请求还要有并发 semaphore，防止慢模型占满连接。Redis 不可用时不是放开，而是进入本地保守桶，比如原配额 10% 且短 TTL。指标看共享桶扣减冲突、上游 429、保守降级触发次数和配额超发。"),
            dict(key="region", q="Model Router 多机房怎么做？为什么不是所有区域共享一个实时队列？", a="Router 适合按区域就近接入，但配额和预算要有全局约束。默认每个区域有本地路由和本地队列，模型健康按区域探测；全局租户日预算由中心存储或周期配额切片下发。RTO 可以做到 5 分钟内切到另一可用区域，RPO 对路由日志可接受 1 分钟内，对预算超发要通过保守切片控制。不是共享一个实时队列，因为跨区排队会增加延迟并扩大故障域；请求 deadline 通常只有几秒，跨区锁不划算。兜底是区域故障时新请求重路由，已在故障区队列里的短 deadline 请求快速失败。指标看跨区切换成功率、预算切片超发和区域健康误判率。"),
            dict(key="tenx", q="模型请求涨 10 倍时，Router 最先坏哪里？怎么提前发现？", a="10 倍流量会先压垮共享限流器、优先队列和慢模型连接池。现象是 route_decision_ms 上升、queue_wait_ms P99 接近 deadline、Redis Lua P99 升高，随后上游 429 和 fallback 风暴增加。提前发现要按 tenant、model、priority 拆指标，不能只看全局成功率。扩容上先把限流 key 分片和本地只读策略缓存做好，再扩 Router 实例；如果共享桶成为瓶颈，按模型族和租户哈希分片。策略上先拒绝低优先级或低预算请求，保护高优先级 deadline。兜底是熔断故障模型并停止多级 fallback，避免备用模型被打爆。指标看重试放大倍数和 fallback 后二次失败率。"),
            dict(key="choice", q="为什么要排队？为什么不直接快速失败或无限重试？", a="选择取决于 deadline 和错误类型。约束是部分请求能等几秒换成功率，部分交互请求等不起。我的方案是按 priority 和 deadline 排队：预计等待小于剩余 deadline 的请求入队，超出就快速失败或降级；队列排序加入 aging 防饥饿。备选是全部快速失败、全部排队、客户端无限重试。全部快速失败浪费短暂抖动恢复窗口；全部排队会制造超时雪崩；无限重试会放大流量。缺点是等待时间预测不准；兜底是队列长度和最大等待硬阈值。指标看排队后成功率增量、超 deadline 比率和低优先级饥饿率。"),
            dict(key="rollout", q="Router 策略怎么灰度、回滚和证明收益？", a="策略灰度必须带 policy_version，并按租户、任务类型、流量百分比逐步放量。每次请求记录候选集、分数、最终模型、fallback_reason、成本、延迟和质量代理分，支持和旧策略做对照。回滚时配置中心把新流量切回旧 policy_version，已排队请求继续按入队时版本执行，避免中途重算造成不一致。止损线包括上游 429 上升 2 个百分点、P99 延迟超过目标、成本每请求上涨超过预算、质量抽检下降。收益要分口径：限流错误下降、成本下降、质量不降。常见陷阱是只看成功率，把切到贵模型导致的成本爆炸藏起来。"),
        ],
        metrics=[
            dict(name="路由成功率", ask="你说 Router 成功率提升，哪些请求算成功？", numerator="在 deadline 内获得可用模型响应且未触发业务不可接受降级的请求数", denominator="所有通过入口鉴权并进入 Router 决策的请求数", exclude="排除客户端主动取消、输入非法、租户预算在入口即为零的请求，因为它们不是路由选择能解决的问题", traps=["把超时后返回降级模板算成功会虚高", "重试成功按 attempt 统计会重复计算", "只看全局会掩盖低优先级饥饿"], answer="采集粒度按 request_id，而不是 attempt。一个请求多次 fallback 最终成功，只算一个成功，同时记录 fallback_depth 和 final_model。展示时按任务类型、优先级、租户和模型拆分，并同时看 deadline 内成功率与最终成功率。如果超出用户 deadline 才返回，即使模型调用成功，也不能算体验成功。环境级供应商整段不可用可以单独标注，但不应从所有报表里悄悄排除。"),
            dict(name="配额超发率", ask="多实例共享配额怎么证明没有放大？", numerator="统计窗口内 tenant+model 实际成功准入量超过配置配额的超出请求数", denominator="同一窗口内 tenant+model 的配置允许请求数或 token 数", exclude="排除人工临时提额且有 policy_version 记录的窗口，因为那是配置变化不是超发", traps=["只按请求数不按 token 会漏掉大请求", "本地降级桶和共享桶重复计数", "窗口边界补充令牌导致误判"], answer="限流器每次扣减记录 key、requested_tokens、granted、remaining、policy_version 和窗口时间。统计时请求数和 token 两个口径都要看，尤其模型成本按 token 变化。窗口边界用滑动窗口或令牌桶理论可用量计算，避免自然补充被误判。这个指标应该非常低；如果 Redis 不可用进入本地保守桶，要单独标识，否则会把保护性降级误解成正常配额。"),
            dict(name="fallback 有效收益", ask="fallback 到底是在救请求，还是在制造更贵更慢的失败？", numerator="首次候选失败后，经允许 fallback 在 deadline 内成功且质量代理分达标的请求数", denominator="所有触发 fallback 的请求数", exclude="排除策略禁止 fallback 的强一致任务，因为这些任务不应该进入该机制", traps=["只看最终成功不看成本", "把参数错误 fallback 算收益", "没有区分 429、超时和内容拒绝原因"], answer="每次 fallback 都要记录 original_model、final_model、error_class、extra_latency_ms、extra_cost 和 quality_proxy。有效收益要求原因是可 fallback 的暂态错误，例如 429 或超时，并且最终在 deadline 内返回；如果是参数错误、内容拒绝或预算耗尽，fallback 成功也可能是策略漏洞。报表看比率、额外成本 P50/P99 和二次失败率，证明 fallback 是救急而不是把所有请求静默导向昂贵模型。"),
        ],
        choices=[
            dict(topic="限流状态存哪里", constraint="Router 多实例部署，本地桶会把租户和模型配额按实例数放大。", choice="选择 Redis 存 tenant+model 令牌桶，并用 Lua 原子补充、扣减和返回 retry_after。", alternatives="备选是每实例本地桶、数据库行锁扣减，或完全依赖上游 429。", why_not="本地桶会超发，数据库行锁在高 QPS 下延迟高，等上游 429 会伤害供应商和用户体验。", downside="缺点是 Redis 成为关键依赖；兜底是本地保守配额、短 TTL 熔断和限流器分片。", metric="用配额超发率、Redis 扣减 P99、上游 429 率和保守降级次数证明。"),
            dict(topic="模型切换边界", constraint="一次 Turn 内模型输出、缓存和工具调用需要一致，中途换模型会破坏上下文语义。", choice="选择只在 Turn 边界切换模型，Turn 内失败按错误类型重试同模型或返回可解释失败。", alternatives="备选是 token 流中途切模型、每个工具调用后重新选模型，或固定全局单模型。", why_not="中途切模型会破坏缓存和一致性，频繁重选难以审计，固定单模型无法处理成本和故障差异。", downside="缺点是 Turn 内遇到慢模型时不能立刻换，可能牺牲一次请求；兜底是严格 deadline 和下个 Turn 降级。", metric="用 Turn 内一致性错误、超时率、跨模型 fallback 质量差和用户重试率证明。"),
        ],
    ),
    "d4": dict(
        pressure=[
            dict(key="core", q="长任务 Workflow 引擎最核心的问题是什么？", a="核心矛盾是开发者想用代码写长流程，但长流程会跨分钟到数天、跨进程重启和人工审批，普通函数调用栈不能作为状态。Workflow 引擎要把代码定义和运行事实分开：WorkflowDef 冻结版本，Run 保存一次执行，NodeState 保存 pending、running、succeeded、failed、waiting_approval，ArtifactStore 保存不可变产物。假设每个 run 10 到 500 个节点，单节点 1 秒到 2 小时，审批可等 7 天。机制是事件溯源加 checkpoint，节点完成后才推进下游。代价是节点函数要确定性、产物要序列化；兜底是非确定逻辑放到 activity 并记录结果。指标看局部重跑成功率、恢复耗时和产物缺失率。"),
            dict(key="scale", q="Workflow 的节点数、产物大小和运行时长如何影响设计？", a="我会先假设每天 1 万个 run，单 run 50 个节点，产物从几 KB 到 500MB，运行时长从 10 分钟到 7 天。小产物可直接放元数据表，大产物必须进对象存储，Checkpoint 只存 artifact_id、hash、size 和 schema_version。节点数超过几百后，调度器不能每次全图扫描，要维护 ready 集合和剩余入度。运行时长超过进程生命周期后，timer、approval 和 signal 都必须持久化，不能靠内存 sleep。规模再大要按 workflow_id 或 run_id 分片调度队列。兜底是限制单 run 最大节点和产物大小，超出拆子 workflow。指标看调度扫描耗时、ArtifactStore 写入 P99 和 timer 触发延迟。"),
            dict(key="authority", q="Workflow 的权威状态在哪里？代码、数据库、日志和产物仓库各自说了算吗？", a="权威要分四类：WorkflowDef 的版本来自代码发布或定义仓库；RunState 和 NodeState 的当前状态在数据库；WorkflowEventLog 记录 append-only 历史，支持确定性重放；ArtifactStore 对产物内容说了算，但只存不可变对象。代码不是运行事实，升级后的代码不能改变已启动 run 的含义；缓存只保存 ready 节点和定义快照。NodeState 至少有 run_id、node_id、status、attempt、lease_token、artifact_refs、definition_version。代价是定义版本和运行版本要长期保留；兜底是无法加载旧版本时暂停 run，而不是用新代码硬跑。指标看重放一致率、旧版本加载失败数和状态日志差异。"),
            dict(key="crash", q="节点写了一半产物、审批信号刚到、持锁执行时进程挂了怎么办？", a="节点执行前写 running 和 lease_token，产物写入采用先写临时对象、校验 hash 后提交不可变 artifact_id，再更新 NodeState 为 succeeded。进程在临时产物阶段挂了，清理任务按 run_id 和 attempt 删除孤儿对象；在产物已提交但状态未写时，恢复可通过 artifact hash 和幂等键补写 checkpoint。审批信号到达先写 SignalEvent，调度器再把 waiting_approval 改 ready，避免信号丢失。持锁死亡靠 lease 过期接管，提交时 CAS token 防止旧 worker 覆盖。代价是多一次对象提交和事件写入；兜底是 unknown 节点不推进下游。指标看孤儿产物数、信号丢失数和 lease 接管 RTO。"),
            dict(key="dup", q="Workflow 中重复信号、乱序事件、节点结果丢失分别怎么处理？", a="重复信号用 signal_id 和 run_id 去重，同一审批单重复点击只记录一次有效决定；乱序事件靠 event_seq 和 expected_version，重放时只接受连续版本。节点重复执行用 node_id、attempt 和 idempotency_key 控制，成功产物是不可变的，重复提交如果 hash 相同可视为幂等命中，hash 不同则标冲突。节点结果丢失时从 ArtifactStore 和 EventLog 对账，能恢复 artifact_ref 就补 checkpoint，不能恢复就只重跑无副作用节点；有副作用节点先查询外部状态。代价是事件表增长快；兜底是按 run 完成后归档。指标看重复信号去重率、事件乱序拒绝数和产物对账成功率。"),
            dict(key="multi", q="多个 worker 同时调度 Workflow，怎么避免同一个节点重复跑？", a="多 worker 下每个 ready 节点领取都要 CAS：NodeState 从 ready 到 running，同时写 owner_id、lease_token、attempt 和 lease_expire_at。worker 心跳续租，提交 succeeded 或 failed 时必须带 token；租约过期后其他 worker 生成更大 fencing token 接管。调度下游时不要由 worker 本地直接推，而是在同一事务里写节点完成事件，再由调度器根据权威 indegree 生成 ready。这样即使两个 worker 都认为自己完成，只有一个能推进下游。代价是数据库事务变重；兜底是把大 run 的调度分片到单 owner，减少冲突。指标看 CAS 冲突、重复执行探测和下游重复 ready 数。"),
            dict(key="region", q="长任务 Workflow 多机房怎么做？RTO/RPO 多少？为什么不是 active-active？", a="Workflow 的 run 内状态强一致，默认单主区域调度、备区复制事件日志和产物元数据。假设普通长任务 RTO 30 分钟，RPO 1 分钟；如果节点有外部副作用，intent 和 completed 事件要同步复制或接管前逐个对账。不是 active-active 的原因是 timer、signal、lease 和下游解锁都依赖同一 event_seq，双主会让审批信号和节点完成乱序。可以做到 active-active 接入，但同一 run 固定 home_region。兜底是主区故障后备区先冻结新调度，重放 EventLog 到一致点，再扫描 running 节点。指标看复制延迟、重放耗时、接管后 unknown 节点数。"),
            dict(key="tenx", q="Workflow 量涨 10 倍最先坏在哪里？如何提前发现和扩容？", a="10 倍后最先坏的是调度扫描、timer 扫描和产物存储，不一定是 worker CPU。每天 1 万 run 涨到 10 万时，如果每秒全表找 ready 和到期 timer，数据库会先抖；大产物也会让对象存储带宽成为瓶颈。提前看 ready_scan_ms、timer_lag_ms、artifact_write_p99、run_event_lag。扩容方式是按 run_id 哈希分片调度器，把 timer 做时间轮或延迟队列，产物走分片对象存储，冷事件归档。执行 worker 可水平扩，但必须受节点类型和外部配额限制。兜底是限制新 run 准入，优先恢复已有 run。指标看 timer P99 触发延迟和 ready 节点积压。"),
            dict(key="choice", q="为什么强调确定性重放？直接从数据库当前状态恢复不行吗？", a="当前状态能让系统继续跑，但无法解释它为什么到这里，也难以在版本升级和 bug 修复后验证一致性。约束是长任务运行数天，期间代码会变，审批和 timer 会穿插。选择确定性重放：Workflow 代码只做纯调度决策，外部调用、时间、随机数和审批都作为事件记录；恢复时重放事件得到同一 ready 集合。备选是只存 NodeState 当前表，或把整个进程内存快照保存。当前表审计弱，内存快照不可移植且版本敏感。缺点是开发者要遵守确定性约束；兜底是非确定逻辑封装成 activity。指标看重放一致率和 replay 耗时。"),
            dict(key="rollout", q="Workflow 引擎或定义升级时，正在跑的 workflow 怎么办？怎么灰度？", a="升级要区分引擎版本和 WorkflowDef 版本。新提交的 run 可以绑定新定义，已运行 run 默认继续使用提交时冻结的 definition_version 和 engine_compat_version。需要迁移时提供显式 migration：从旧 NodeState 映射到新节点图，声明哪些节点可复用、哪些下游要清理。灰度按 workflow 类型和新 run 百分比开启；回滚时停止新版本提交，旧 run 继续按绑定版本跑。止损线是 replay 不一致、timer 延迟上升、节点失败率上升。证明收益看局部重跑耗时下降、人工审批等待不丢、失败恢复率提高。不能用“测试通过”替代线上旧 run 兼容性，要抽样重放历史事件。"),
        ],
        metrics=[
            dict(name="局部重跑成功率", ask="你说失败后支持局部重跑，分母是什么？", numerator="从指定失败节点或变更节点开始，清理受影响下游后成功恢复到一致完成或等待状态的 run 数", denominator="所有触发局部重跑且上游依赖产物仍在保留期内的 run 数", exclude="排除上游产物已按 TTL 合法清理、旧定义版本无法加载且无迁移声明的 run，因为它们不满足重跑前提", traps=["把整条 workflow 重跑成功算局部成功", "没有清理下游旧产物会假成功", "按节点统计会掩盖 run 级不一致"], answer="每次局部重跑记录 rerun_id、start_node、cleared_nodes、reused_artifacts 和 definition_version。成功要求被清理下游重新生成的 artifact hash 和 NodeState 都一致，未受影响上游不能被改写。统计按 run 级主口径，节点级用于定位。还要看局部重跑节省的执行时间和外部副作用跳过次数，否则只是换一种全量重跑。"),
            dict(name="确定性重放一致率", ask="怎么证明 Workflow 可以确定性恢复？", numerator="同一 EventLog 在相同 WorkflowDef 版本下重放得到的 NodeState、ready 集合和 timer 集合完全一致的次数", denominator="所有进行恢复演练、版本升级校验或实际接管重放的次数", exclude="排除事件日志缺失、定义版本被人工删除的样本，并单独作为运维缺陷统计", traps=["只比较最终成功不比较中间 ready 集合", "忽略 timer 和 signal 会漏掉长任务问题", "用新定义重放旧 run 却不声明迁移"], answer="采集时恢复流程输出 replay_digest，包含每个节点状态、artifact_ref、timer_id 和 signal_consumed 集合。线上可以定期对完成 run 做离线重放，对正在跑的 run 在接管前重放到最新 event_seq。主指标看一致率，辅助看 replay 耗时 P99。任何不一致都要阻止自动接管，因为继续跑可能解锁错误下游或重复副作用。"),
            dict(name="审批信号准时处理率", ask="人工审批前暂停、审批后继续，怎么量化？", numerator="审批信号写入后在目标时间内使对应节点从 waiting_approval 进入 ready、rejected 或 timed_out 的次数", denominator="所有合法审批信号和到期审批 timer 数", exclude="排除无权限审批、审批单已取消、run 已终止的信号，因为它们不应该推进状态", traps=["只看审批接口 200 不看 workflow 状态", "重复点击导致分母膨胀", "超时默认策略和人工拒绝混在一起"], answer="Approval 表记录 approval_id、run_id、node_id、status、signal_id、actor_role、received_at 和 applied_at。口径上同一 approval_id 多次点击只算一次合法信号，接口成功但 NodeState 没变化不算处理成功。展示时看比率和 applied_at-received_at 的 P50/P99，另外分开看 approved、rejected、timed_out 三类，避免用平均值掩盖超时策略错误。"),
        ],
        choices=[
            dict(topic="状态模型", constraint="长任务会跨重启、审批和版本升级，当前内存调用栈无法作为可恢复事实。", choice="选择事件溯源加节点 checkpoint，事件用于重放，当前表用于快速查询 ready 和状态。", alternatives="备选是只保存数据库当前状态、保存进程快照，或把 workflow 拆成普通定时任务。", why_not="当前状态审计和迁移弱，进程快照版本敏感，普通定时任务难表达依赖和局部重跑。", downside="缺点是事件量大且开发者要写确定性逻辑；兜底是事件归档、replay digest 和 activity 边界。", metric="用确定性重放一致率、恢复 RTO、事件存储成本和局部重跑成功率证明。"),
            dict(topic="产物存储", constraint="节点之间只传产物，产物可能很大且必须在局部重跑和审计时可复用。", choice="选择不可变 ArtifactStore，Checkpoint 只保存 artifact_id、hash、size 和 schema_version。", alternatives="备选是把产物直接塞数据库、传共享内存对象，或下游重新调用上游获取结果。", why_not="数据库不适合大对象，共享内存不可恢复，重新获取会破坏确定性并可能重复成本。", downside="缺点是对象存储清理和版本兼容复杂；兜底是引用计数、TTL 策略和读取 hash 校验。", metric="用产物缺失率、artifact 读取 P99、孤儿对象数量和局部重跑复用率证明。"),
        ],
    ),
    "d5": dict(
        pressure=[
            dict(key="core", q="多用户 Agent Session 服务最核心的问题是什么？", a="核心矛盾是同一会话必须按消息顺序串行推进，才能保持上下文一致；但全站有大量用户和会话，又必须会话间并行、断线可恢复、空闲可回收。假设 10 万在线用户、100 万会话、入口 2 千 QPS，单会话消息处理 5 到 60 秒。机制上用 SessionQueue 保存输入顺序，ActiveSession/lease 保证单 owner，SessionState 保存上下文，EventBuffer 保存有序输出。代价是热点会话天然串行，延迟可能高；兜底是单会话限速、公平调度和队列满拒绝。指标看会话内乱序数、队列等待 P99、断线补发成功率和热点会话占用率。"),
            dict(key="scale", q="这个 Session 服务按多大用户量和状态量设计？规模变化会改变什么？", a="我会假设每个用户 1 到 20 个会话，活跃会话 10 万，单会话热上下文 100KB 到 2MB，事件缓冲 1 千到 1 万条，空闲 TTL 30 分钟。小规模可用单库分片加内存 LRU；当活跃会话超过百万或热状态超过 TB 级，关键决定会变成 session_id 一致性哈希、状态冷热分层和事件归档。入口 QPS 增长时，worker 池不是无限扩，因为同一 session 仍串行；扩的是不同 session 的并行度和持久队列吞吐。兜底是限制单会话队列长度，比如 100 条，超过返回 429。指标看活跃会话数、每会话队列长度、缓存回源 P99。"),
            dict(key="authority", q="Session owner、上下文和事件序列谁说了算？粘性路由可靠吗？", a="权威状态在持久化 SessionState、SessionQueue、ActiveSession lease 和 EventBuffer。粘性路由只是优化，让同一 session 尽量打到 owner 实例，减少加载热状态；它不能替代 lease，因为实例摘除、网络抖动或重启都会让粘性失效。ActiveSession 字段包括 session_id、owner_id、lease_token、fencing_token、expire_at、state_version。上下文更新必须带 version CAS，事件 seq 由权威存储或 owner 在 lease 内分配并落盘。代价是每条消息有状态读写；兜底是 owner 丢失后从持久状态重建。指标看粘性命中率、owner 接管次数和旧 owner 拒写数。"),
            dict(key="crash", q="worker 处理一半崩溃、客户端断线、实例摘除时分别怎么办？", a="用户输入只有写入 SessionQueue 后才返回接收成功，worker 领取 session 后持有 lease。处理一半崩溃时，lease 过期，其他实例接管；已落盘的 SessionState 和 EventBuffer 继续复用，未落盘的模型中间态视为未承诺。客户端断线不影响后端处理，重连带 last_event_id 从 EventBuffer 补发。实例摘除要先停止接新 session，续租失败后把热会话转移；如果强杀，则靠 lease TTL，比如 30 秒内接管。代价是 TTL 太短会误接管，太长恢复慢；兜底是心跳延迟自适应和摘除前 drain。指标看接管 RTO、补发缺口和 drain 成功率。"),
            dict(key="dup", q="重复消息、事件乱序、队列消息丢失怎么处理？", a="重复消息用 request_id 去重，SessionQueue 里保存 input_seq、request_id、payload_hash，同一 request_id 返回同一个 input_seq。事件乱序靠 session 内 event_seq，服务端按 seq 落盘，客户端按 seq 去重和缓冲。队列消息丢失的防线是先持久化再 ack，内存队列只做加速；如果发现 input_seq 缺口，session 进入 repair 状态，不继续处理后续消息，避免基于缺失上下文回答。重复事件补发不是失败，只要 seq 和 payload_hash 一致即可。代价是 request_id 需要客户端配合；兜底是服务端生成短期去重指纹。指标看重复请求命中、seq 缺口和修复耗时。"),
            dict(key="multi", q="多实例部署时如何避免同一个 session 被两个 worker 同时处理？", a="多实例要用 owner lease 加 fencing token。调度器领取 session 时 CAS ActiveSession：空闲或过期才能写 owner_id、lease_token、fencing_token 和 expire_at。worker 处理每条消息时带 token 更新 SessionState 和 EventBuffer；旧 owner 即使还活着，因 token 过期或 fencing 更小会被拒写。负载均衡层做粘性路由，但只是把请求送到当前 owner；如果 owner 不匹配，请求要转发或只入持久队列。代价是跨实例转发增加一次跳转；兜底是 owner 不可达时让 lease 过期再接管。指标看双 owner 探测数、CAS 冲突率、跨实例转发率。"),
            dict(key="region", q="Session 服务多机房怎么做？RTO/RPO 多少？为什么不是 active-active？", a="同一 session 的消息和事件有严格顺序，默认把 session 固定到 home_region，其他区域只做就近入口和只读查询。SessionState、Queue 和 EventBuffer 异步复制，普通会话 RTO 10 分钟，RPO 30 秒内；高价值会话可以同步复制输入队列和事件日志，把 RPO 压到接近 0。不是对同一 session active-active，因为两个区域会同时分配 input_seq 和 event_seq，合并冲突代价高。可以按 session 粒度 active-active，不同 session 分布在不同区域。兜底是主区故障后备区冻结新输入，重放到最大连续 seq，再开放接管。指标看复制 lag、跨区接管成功率和序列冲突数。"),
            dict(key="tenx", q="用户和会话量涨 10 倍，先坏在哪？如何扩容？", a="10 倍增长下先坏的是 SessionQueue 存储、热状态缓存和热点用户公平性。全局 worker 可以横向扩，但热点 session 仍只能串行，队列会越积越长；LRU 命中下降会导致状态回源 P99 上升。提前发现看 active_session_count、queue_len_per_session P99、cache_miss_load_ms、user_worker_share。扩容先按 session_id 分片队列和状态表，再加 worker；缓存按热会话分层，事件日志冷热分离。策略上限制单用户活跃 session 和单 session 队列长度，避免一个租户占满 worker。兜底是低优先级会话转离线或返回背压。指标看队列等待 P99 和公平性指标。"),
            dict(key="choice", q="为什么选择会话内串行？能不能同一 session 多消息并行提高吞吐？", a="约束是 Agent 上下文是有序状态，后一条消息必须看到前一条消息产生的 messages、memory 和工具结果。同一 session 并行会产生读旧版本、覆盖写和事件乱序，所以选择会话内串行、会话间并行。备选是乐观并发合并、按消息独立上下文执行，或全局串行。乐观合并只适合无状态命令，Agent 结果很难自动合并；独立上下文会答非所问；全局串行吞吐太低。缺点是热点会话延迟高；兜底是限速、拆子会话和让出调度权。指标看上下文冲突数、热点队列等待和会话间吞吐。"),
            dict(key="rollout", q="Session owner 路由、空闲回收和记忆策略怎么灰度、回滚、证明收益？", a="灰度按租户和 session_id 哈希开启 owner lease、粘性路由和 LRU+TTL 回收，每个事件记录 session_runtime_version。回滚时停止新会话进入新版，已有 owner lease 等 TTL 自然释放，不能强行删除 SessionState 或 EventBuffer。记忆策略要用影子评估：新摘要不直接覆盖旧上下文，先记录 memory_version、引用命中和人工或自动质量评分。止损线是会话内乱序非零、补发缺口上升、缓存回源 P99 超目标、用户重试率上升。收益看内存占用下降、接管 RTO 不变、上下文有效性不降。口径陷阱是只看缓存命中而不看回答质量。"),
        ],
        metrics=[
            dict(name="会话内有序处理率", ask="你说同一 session 串行且事件有序，怎么量化？", numerator="没有 input_seq 缺口、没有并发 owner、输出 event_seq 连续的已处理会话消息数", denominator="所有进入 SessionQueue 并被 worker 开始处理的会话消息数", exclude="排除用户主动删除会话后到达的旧重连请求，因为它们不应继续原序列", traps=["按 HTTP 请求统计会把重试放大", "只看输入顺序不看输出事件", "重复补发事件不等于乱序"], answer="每条消息有 input_seq，每个输出有 event_seq，worker 更新状态时记录 owner_token 和 state_version。成功要求该消息处理期间只有一个有效 owner，输入 seq 连续，输出 seq 没有不可补齐缺口。主口径按消息统计，另按 session 统计是否出现过乱序。看比率之外，还要看乱序修复耗时和旧 owner 拒写次数，因为偶发冲突如果能被 fencing 拦住，不一定影响用户。"),
            dict(name="断线补发成功率", ask="客户端断线重连后补发成功率的分母是什么？", numerator="客户端带 last_event_id 重连后，在保留窗口内补齐到当前最大连续 event_seq 的重连次数", denominator="所有合法重连且 last_event_id 落在 EventBuffer 保留窗口内的次数", exclude="排除 last_event_id 早于 TTL、session 已被用户删除、客户端身份不匹配的重连请求", traps=["把重复事件补发当失败", "只看 WebSocket 连接成功不看事件补齐", "按事件条数统计会掩盖一次重连失败"], answer="重连时服务端记录 session_id、last_event_id、from_seq、to_seq、missing_count 和补发耗时。成功不是连接建立，而是 EventBuffer 能从 last_event_id+1 补到当前最大连续 seq，并且 payload_hash 校验一致。展示时按重连次数为主，事件条数为辅，同时看补发耗时 P99 和 ack_lag。TTL 外请求单独统计为过期，不混入服务承诺内的失败。"),
            dict(name="上下文有效命中率", ask="你说上下文和记忆有效，怎么避免只看缓存命中？", numerator="回答中实际引用的 session memory 或摘要被后续验证为相关且未过期的次数", denominator="所有回答尝试读取 session memory、摘要或历史上下文的次数", exclude="排除显式无上下文问题、用户关闭记忆、合规策略要求不读取历史的请求", traps=["缓存命中不等于语义有效", "按 token 占比统计会奖励塞入无关历史", "只看人工好评会有样本偏差"], answer="采集时把每次读取的 memory_id、summary_version、created_at、引用片段和回答 trace 关联起来。有效可以来自用户确认、自动一致性检查或抽样人工标注，但必须区分相关、过期、冲突和未使用。主指标按读取次数统计，同时看引入上下文后的回答成功率和延迟成本。常见陷阱是缓存命中率很高但模型没有使用，或者使用了过期记忆导致错误。"),
        ],
        choices=[
            dict(topic="Session owner 路由", constraint="同一 session 要串行处理，但多实例和实例摘除要求可接管。", choice="选择粘性路由加 ActiveSession lease 和 fencing token，粘性提速，lease 做权威互斥。", alternatives="备选是只靠负载均衡粘性、全局分布式锁，或所有请求都读写共享状态无 owner。", why_not="单靠粘性故障时会双写，全局锁成本高，无 owner 会让每次状态更新都变慢。", downside="缺点是 owner 转移和跨实例转发复杂；兜底是短 lease、drain 机制和旧 token 拒写。", metric="用粘性命中率、接管 RTO、双 owner 探测数和状态更新 P99 证明。"),
            dict(topic="空闲回收策略", constraint="活跃会话很多，热上下文占内存，但未完成队列和未 ack 事件不能丢。", choice="选择 LRU+TTL 只回收内存热状态，持久 SessionState、Queue 和 EventBuffer 保留到安全水位。", alternatives="备选是永不回收、TTL 到期删除整个会话，或每次请求都从冷存储加载。", why_not="永不回收内存不可控，整会话删除会丢任务和事件，每次冷加载延迟太高。", downside="缺点是回收后首请求会变慢且 TTL 难调；兜底是预热热点会话和按 ack 水位延迟清理。", metric="用内存占用、缓存命中率、回源加载 P99、补发缺口率和误回收数证明。"),
        ],
    ),
}
